UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 37, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 38, 7, NULL::text),(3, 166, 27, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 197, 1014, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='d26bd4ba-0c37-5e20-83e3-941607220488' AND md5(a.contenido)='35dde9f4a7946a081e4664bcedbb11fc' RETURNING a.id,md5(a.contenido) hash;